-- GLOBAL CALENDAR & TASKS (MySQL 8.0)
-- The current development database was reconciled manually through phpMyAdmin.
-- This file is source-control migration history for clean/legacy installations only.
-- DO NOT execute it against the current development database from this repository.

SET @schema_name := DATABASE();

-- MySQL 8 does not support ADD COLUMN IF NOT EXISTS.  Each operation therefore
-- uses INFORMATION_SCHEMA plus PREPARE/EXECUTE and is safe for clean installs.
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='event_code')=0, 'ALTER TABLE calendar_events ADD COLUMN event_code VARCHAR(80) NULL AFTER business_unit_id', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='location_name')=0, 'ALTER TABLE calendar_events ADD COLUMN location_name VARCHAR(220) NULL AFTER description', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='source_module_code')=0, 'ALTER TABLE calendar_events ADD COLUMN source_module_code VARCHAR(80) NULL AFTER event_type', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='status_code')=0, 'ALTER TABLE calendar_events ADD COLUMN status_code VARCHAR(30) NOT NULL DEFAULT ''scheduled'' AFTER all_day', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='reminder_minutes_before')=0, 'ALTER TABLE calendar_events ADD COLUMN reminder_minutes_before INT UNSIGNED NULL AFTER status_code', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='source_code')=0, 'ALTER TABLE calendar_events ADD COLUMN source_code VARCHAR(120) NULL AFTER source_id', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='source_key')=0, 'ALTER TABLE calendar_events ADD COLUMN source_key VARCHAR(190) NULL AFTER source_code', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='updated_by')=0, 'ALTER TABLE calendar_events ADD COLUMN updated_by BIGINT UNSIGNED NULL AFTER created_by', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='calendar_events' AND COLUMN_NAME='deleted_at')=0, 'ALTER TABLE calendar_events ADD COLUMN deleted_at DATETIME(3) NULL AFTER updated_at', 'SELECT 1'); PREPARE calendar_ddl FROM @sql; EXECUTE calendar_ddl; DEALLOCATE PREPARE calendar_ddl;

SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='tasks' AND COLUMN_NAME='start_at')=0, 'ALTER TABLE tasks ADD COLUMN start_at DATETIME(3) NULL AFTER priority_code', 'SELECT 1'); PREPARE task_ddl FROM @sql; EXECUTE task_ddl; DEALLOCATE PREPARE task_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='tasks' AND COLUMN_NAME='reminder_minutes_before')=0, 'ALTER TABLE tasks ADD COLUMN reminder_minutes_before INT UNSIGNED NULL AFTER due_at', 'SELECT 1'); PREPARE task_ddl FROM @sql; EXECUTE task_ddl; DEALLOCATE PREPARE task_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='tasks' AND COLUMN_NAME='source_module_code')=0, 'ALTER TABLE tasks ADD COLUMN source_module_code VARCHAR(80) NULL AFTER reminder_minutes_before', 'SELECT 1'); PREPARE task_ddl FROM @sql; EXECUTE task_ddl; DEALLOCATE PREPARE task_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='tasks' AND COLUMN_NAME='source_code')=0, 'ALTER TABLE tasks ADD COLUMN source_code VARCHAR(120) NULL AFTER source_id', 'SELECT 1'); PREPARE task_ddl FROM @sql; EXECUTE task_ddl; DEALLOCATE PREPARE task_ddl;
SET @sql := IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='tasks' AND COLUMN_NAME='source_key')=0, 'ALTER TABLE tasks ADD COLUMN source_key VARCHAR(190) NULL AFTER source_code', 'SELECT 1'); PREPARE task_ddl FROM @sql; EXECUTE task_ddl; DEALLOCATE PREPARE task_ddl;
